-- Patch one record, logging instead of aborting when gen1recomp refuses it,
-- so a single bad record never takes the rest of the mod down with it.
local function patch(mod, registry, id, fields, stats)
  local reg = mod.content[registry]
  if not reg then
    mod.log:warn("registry %s is not available; skipped %s", registry, tostring(id))
    stats.failed = stats.failed + 1
    return
  end
  local ok, result, reason = pcall(reg.patch, reg, id, fields)
  if not ok or (result == nil and reason ~= nil) then
    mod.log:warn("%s %s: %s", registry, tostring(id), tostring(ok and reason or result))
    stats.failed = stats.failed + 1
  else
    stats.applied = stats.applied + 1
  end
end

-- Deterministic iteration, so load order (and any warnings) is reproducible.
local function each(map, fn)
  local keys = {}
  for k in pairs(map) do keys[#keys + 1] = k end
  table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
  for _, k in ipairs(keys) do fn(k, map[k]) end
end

-- Write custom DVs / stat exp / happiness onto a built trainer party.
-- gen1recomp gives trainer mons the vanilla fixed DVs; this hook runs before
-- the battle computes stats, so the values here are what the battle uses.
local function wrapTrainerExtras(mod, extras, memberIndex)
  if next(extras) == nil then return end
  mod.hooks:wrap("trainer.party", function(nextFn, class, member, party)
    party = nextFn(class, member, party)
    local index = type(member) == "string" and memberIndex[member] or member
    local slots = extras[class] and extras[class][index]
    if slots and type(party) == "table" then
      for slot, extra in pairs(slots) do
        local mon = party[slot]
        if mon then
          if extra.dvs then mon.dvs = extra.dvs end
          if extra.statExp then mon.statExp = extra.statExp end
          if extra.happiness then mon.happiness = extra.happiness end
        end
      end
    end
    return party
  end)
end
-- BEGIN legacy_options (shared; edit tools/legacy_options.lua, not a copy)
-- One "CRYSTAL LEGACY" row in the pause OPTIONS menu, opening a page with the
-- settings of every installed Legacy mod. Each mod still defines its settings
-- with mod.options:define, so the MODS menu keeps showing them per mod; both
-- views save through ManagerState:setOption, the same storage, so they agree.
--
-- Mods cannot load each other's files, so every Legacy mod with settings
-- carries this block and registers into a table on the ManagerState module.
-- Whichever loads first installs the row and the page; later ones only add
-- their settings to the table.
local function legacyOptionsPage(mod, schema, label)
  local okM, ManagerState = pcall(require, "src.mods.ManagerState")
  if not (okM and type(ManagerState) == "table") then return end
  local reg = rawget(ManagerState, "__crystalLegacyOptions")
  -- A mod registering twice means the mods were reloaded: start over, so the
  -- row and the page are installed into the new load.
  if not reg or reg.mods[mod.id] then
    reg = { mods = {}, installed = false }
    ManagerState.__crystalLegacyOptions = reg
  end
  reg.mods[mod.id] = { label = label, schema = schema, mod = mod }
  if reg.installed then return end
  reg.installed = true

  local SCREEN = "CrystalLegacyOptions"

  local function current(entry, row)
    local v = entry.mod.options:get(row.key)
    if v == nil then v = row.default end
    return v
  end

  local function save(game, modId, key, value)
    -- ManagerState's own setter, so the MODS menu sees the same value.
    local proxy = setmetatable({ game = game }, { __index = ManagerState })
    local ok = pcall(ManagerState.setOption, proxy, modId, key, value)
    return ok
  end

  local function buildRows()
    local ids = {}
    for id in pairs(reg.mods) do ids[#ids + 1] = id end
    table.sort(ids, function(a, b) return reg.mods[a].label < reg.mods[b].label end)
    local rows = {}
    for _, id in ipairs(ids) do
      local entry = reg.mods[id]
      rows[#rows + 1] = { header = true, label = entry.label,
        value = function() return "" end }
      for _, row in ipairs(entry.schema) do
        if row.type == "toggle" then
          rows[#rows + 1] = {
            label = row.label,
            value = function() return current(entry, row) and "ON" or "OFF" end,
            step = function(game) save(game, id, row.key, not current(entry, row)) end,
          }
        elseif row.type == "choice" and type(row.choices) == "table" and #row.choices > 0 then
          local function at()
            local v = current(entry, row)
            for i, c in ipairs(row.choices) do if c[2] == v then return i end end
            return 1
          end
          rows[#rows + 1] = {
            label = row.label,
            value = function() return tostring(row.choices[at()][1]) end,
            step = function(game, dir)
              local n = #row.choices
              save(game, id, row.key, row.choices[(at() - 1 + (dir or 1)) % n + 1][2])
            end,
          }
        end
      end
    end
    return rows
  end

  local function selectable(rows, i) return rows[i] and not rows[i].header end

  local function newScreen(game)
    local OptionRows = require("src.ui.OptionRows")
    local rows = buildRows()
    local screen = { game = game, rows = rows, index = 1, scroll = 0, isOpaque = true }
    while screen.index < #rows and not selectable(rows, screen.index) do
      screen.index = screen.index + 1
    end
    local function move(self, dir)
      local n = #self.rows
      for _ = 1, n do
        self.index = (self.index - 1 + dir) % n + 1
        if selectable(self.rows, self.index) then return end
      end
    end
    function screen:update()
      local input = self.game.input
      if input:wasPressed("up") then
        move(self, -1)
      elseif input:wasPressed("down") then
        move(self, 1)
      elseif input:wasPressed("left") or input:wasPressed("right") or input:wasPressed("a") then
        local row = self.rows[self.index]
        local dir = input:wasPressed("left") and -1 or 1
        if row and row.step then row.step(self.game, dir) end
      elseif input:wasPressed("b") then
        self.game.stack:pop()
        return
      end
      self.scroll = OptionRows.clampScroll(self.index, self.scroll, #self.rows, nil)
    end
    function screen:draw()
      OptionRows.draw(self.game, self.rows, self.index, self.scroll, "A/<>:CHANGE B:DONE")
    end
    return screen
  end

  pcall(mod.content.screens.register, mod.content.screens, SCREEN, { new = newScreen })
  reg.newScreen = newScreen -- for tests

  mod.hooks:wrap("ui.options.rows", function(nextFn, game, rows)
    local out = nextFn(game, rows)
    if type(out) ~= "table" then return out end
    local row = {
      id = "crystal_legacy:options",
      label = "CRYSTAL LEGACY",
      value = function() return "OPEN" end,
      activate = function(g) require("src.ui.Screens").push(g, SCREEN) end,
    }
    if mod.ui and type(mod.ui.insertBefore) == "function" then
      return mod.ui.insertBefore(out, "MODS", row)
    end
    out[#out + 1] = row
    return out
  end)
end
-- END legacy_options

local function iconRgba(palette)
  -- GBC OBJ palette: colour 0 is transparent, then light, dark, black.
  local out = {}
  for i, c in ipairs(palette) do out[i] = { c[1] / 31, c[2] / 31, c[3] / 31, i == 1 and 0 or 1 } end
  return out
end

-- Which of the palette's four slots a pixel is. Crystal Legacy's icon files
-- are already coloured: white (transparent), a peach shared by every
-- palette, the species colour, and black. Matching the three fixed colours
-- and calling everything else the species colour is what keeps a saturated
-- blue (Wooper, Totodile, Marill) from passing for the peach by brightness.
local FIXED -- { white, peach, black } as 0-1 RGB, from DATA.palettes
local function slotOf(r, g, b)
  if not FIXED then
    local p = DATA.palettes.RED
    FIXED = { { 1, p[1] }, { 2, p[2] }, { 4, p[4] } }
  end
  local best, bestD = 3, 0.06 -- squared distance; anything farther is the species colour
  for _, f in ipairs(FIXED) do
    local c = f[2]
    local dr, dg, db = r - c[1] / 31, g - c[2] / 31, b - c[3] / 31
    local d = dr * dr + dg * dg + db * db
    if d < bestD then best, bestD = f[1], d end
  end
  if best ~= 3 then return best end
  -- A plain grey file (Ho-Oh still uses one): light grey is the light slot,
  -- dark grey the species colour. In the coloured files the only grey is the
  -- GRAY palette's species colour, which is dark.
  if math.abs(r - g) < 0.02 and math.abs(g - b) < 0.02 and r > 0.5 then return 2 end
  return 3
end

local function legacyMenuIcons(mod)
  local ICON_OPTIONS = {
    { key = "useWilds", label = "USE WILDS SPRITES", type = "toggle", default = true },
  }
  mod.options:define(ICON_OPTIONS)
  legacyOptionsPage(mod, ICON_OPTIONS, "MENU ICONS")
  local okA, Assets = pcall(require, "src.render.Assets")
  if not (okA and Assets and Assets.compose) then
    mod.log:warn("asset module not found; Legacy menu icons disabled")
    return
  end
  -- The mod's own folder, through the sandbox's mod:info (love.filesystem
  -- is off limits to mods).
  local function present(file)
    local ok, info = pcall(mod.info, mod, "icons/" .. file)
    return ok and type(info) == "table" and info.type == "file"
  end
  local found, missing = 0, 0
  local registered = {}
  -- One composed image per species and palette, built from the player's own
  -- file the first time the party menu asks for it.
  local function composedPath(species, shiny)
    local rec = DATA.icons[species]
    if not rec then return nil end
    if not present(rec.file) then return nil end
    local src = mod.path .. "/icons/" .. rec.file
    local key = "legacy-icons/" .. species .. (shiny and "-shiny" or "") .. ".png"
    if not registered[key] then
      local colours = iconRgba(DATA.palettes[shiny and rec.shiny or rec.normal]
        or DATA.palettes.RED)
      Assets.compose(key, function()
        -- loaded by the engine's asset layer, outside the mod sandbox
        local img = Assets.imageData(src)
        img:mapPixel(function(_, _, r, g, b, a)
          if a == 0 then return 0, 0, 0, 0 end
          local c = colours[slotOf(r, g, b)]
          return c[1], c[2], c[3], c[4]
        end)
        return img
      end)
      registered[key] = true
    end
    return key
  end
  mod.exports.composedPath = composedPath
  mod.exports.slotOf = slotOf

  -- Fallback source: Wilds of Kanto (overworld_wild_spawns), when installed.
  -- Its resolveFollowerSprite picks the sheet for the player's chosen Sprite
  -- Style; a classic 16x16 walking sheet (idle_down, idle_up, idle_left,
  -- walk_down, ...) becomes a two-frame icon: idle_down over walk_down.
  local wildsResolver -- tests may set one through mod.exports
  local function wildsSheet(species, shiny)
    local resolve = wildsResolver
    if not resolve then
      local wilds = mod:find("overworld_wild_spawns")
      resolve = wilds and wilds.exports and wilds.exports.resolveFollowerSprite
    end
    if type(resolve) ~= "function" then return nil end
    local ok, def = pcall(resolve, { species = species, shiny = shiny == true,
      surface = "land", game = mod.game })
    if not ok or type(def) ~= "table" or def.fallback or type(def.image) ~= "string" then
      return nil
    end
    if (def.frameWidth or 16) ~= 16 or (def.frameHeight or 16) ~= 16 or (def.frames or 6) < 4 then
      return nil -- HGSS true-size, PMDCollab etc.: not icon-shaped
    end
    return def.image
  end
  local wildsCache_reset -- set below, once the cache exists
  mod.exports.setWildsResolver = function(fn)
    wildsResolver = fn
    if wildsCache_reset then wildsCache_reset() end
  end

  -- The party menu asks every frame; Wilds' answer is cached per species and
  -- shininess (a Sprite Style change in Wilds shows after a restart).
  local wildsCache = {}
  wildsCache_reset = function() wildsCache = {} end
  local function wildsIconPath(species, shiny)
    if mod.options:get("useWilds") == false then return nil end
    local ck = tostring(species) .. (shiny and ":shiny" or ":normal")
    if wildsCache[ck] ~= nil then return wildsCache[ck] or nil end
    local image = wildsSheet(species, shiny)
    if not image then wildsCache[ck] = false return nil end
    if not image then return nil end
    local key = "wilds-icons/" .. image
    if not registered[key] then
      Assets.compose(key, function()
        local src = Assets.imageData(image)
        local out = love.image.newImageData(16, 32)
        out:paste(src, 0, 0, 0, 0, 16, 16)   -- idle_down
        out:paste(src, 0, 16, 0, 48, 16, 16) -- walk_down
        return out
      end)
      registered[key] = true
    end
    wildsCache[ck] = key
    return key
  end
  mod.exports.wildsIconPath = wildsIconPath

  for species, rec in pairs(DATA.icons) do
    if present(rec.file) then found = found + 1 else missing = missing + 1 end
  end
  if found == 0 then
    mod.log:info("no icons in %s/icons yet; copy Crystal Legacy's gfx/icons folder there", mod.path)
  else
    mod.log:info("Legacy menu icons: %d species found, %d missing", found, missing)
  end

  mod.hooks:wrap("pokemon.icon", function(nextFn, path, ctx)
    path = nextFn(path, ctx)
    local mon = ctx and ctx.mon
    local species = (ctx and ctx.species) or (mon and mon.species)
    if not species or (mon and mon.isEgg) then return path end
    local key = composedPath(species, mon and mon.shiny)
      or wildsIconPath(species, mon and mon.shiny)
    if not key then return path end
    ctx.trueColor = true
    return key
  end)
end

return function(mod)
  local stats = { applied = 0, failed = 0 }

  legacyMenuIcons(mod)
  mod.log:info("Legacy: Menu Icons: %d patches applied, %d refused", stats.applied, stats.failed)
end
